"""Evaluate frozen QA-44 in 100 simple two-room dungeons generated by PcgDungeonManager."""

import argparse
from collections import Counter
from datetime import datetime, timezone
import gzip
import json
from pathlib import Path
import shutil
import socket
import subprocess

from run_local_movement import GAME, checkpoint_hash, save
from run_waypoint_chain import ready, finish, records
from test_waypoint_reach import UNITY
from unity_env import UnityGymEnv
import numpy as np
import torch
from stable_baselines3 import PPO


CHECKPOINT = GAME / 'SavedModels/qa/local-waypoint-v1/qa-waypoint-throughput-20261108-233001-train/final_model.zip'
SHA256 = '1094cd0cea9a3fe2bc183b5bd3a7c1dc2ea6d22f4d5d5939629d7ed7ccafde8e'
SOURCES = [
    'Assets/Editor/QaTwoRoomNavigationSession.cs',
    'Assets/PCGDungeon/Scripts/Generation/PcgDungeonManager.cs',
    'Assets/PCGDungeon/Scripts/Generation/Generator.cs',
    'Assets/PCGDungeon/Scripts/Generation/Room.cs',
    'Assets/PCGDungeon/Scripts/QA/ModelSensorPackage.cs',
    'Assets/PCGDungeon/Scripts/QA/QaMapNavigation.cs',
    'Assets/PCGDungeon/Scripts/QA/QaPlayerController.cs',
    'Assets/PCGDungeon/Scripts/QA/QaExitZone.cs',
    'Assets/PCGDungeon/Scripts/Policy/QaWaypointPolicyMapping.cs',
    'Assets/Scenes/QaPlayerTraining.unity',
    'Assets/PCGDungeon/Settings/Settings.asset',
    'Training/evaluate_two_room_navigation.py',
]


def summary(rows):
    successes = [r for r in rows if r['completed']]
    failures = [r for r in rows if not r['completed']]
    return dict(episodes=len(rows), exits_reached=len(successes),
        success_rate=len(successes) / len(rows), timeouts=sum(r['reason'] == 'timeout' for r in rows),
        successful_seconds_mean=float(np.mean([r['elapsed_seconds'] for r in successes])) if successes else None,
        all_attempt_seconds_mean=float(np.mean([r['elapsed_seconds'] for r in rows])),
        failures_by_final_phase=dict(Counter(r['final_phase'] for r in failures)),
        failures_entering_exit_room=sum(r['entered_exit_room'] for r in failures),
        waypoint_arrivals=sum(r['waypoint_arrivals'] for r in rows),
        assignments=sum(r['assignments'] for r in rows), replans=sum(r['replans'] for r in rows),
        actions=sum(r['steps'] for r in rows), low_movement_actions=sum(r['low_movement_actions'] for r in rows),
        no_waypoint_actions=sum(r['no_waypoint_actions'] for r in rows),
        away_or_perpendicular_actions=sum(r['away_actions'] for r in rows))


def phase(directory, name, seeds, model=None, idle=False):
    output = directory / name
    output.mkdir()
    process = subprocess.Popen([str(UNITY), '-batchmode', '-nographics', '-projectPath', str(GAME),
        '-executeMethod', 'QaTwoRoomNavigationSession.Run', '-trainingRunDirectory', str(output),
        '-logFile', str(output / 'unity.log')], cwd=GAME, creationflags=subprocess.CREATE_NO_WINDOW)
    save(output / 'process.json', dict(unity_pid=process.pid))
    environment = None
    try:
        ready(output, process)
        environment = UnityGymEnv(port=7784, timeout_seconds=300)
        environment._socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        for i, seed in enumerate(seeds):
            observation, _ = environment.reset(seed=seed)
            assert observation.shape == (134,) and observation[0] == observation[1] == 0
            done = False
            steps = 0
            while not done:
                if model is not None:
                    action, _ = model.predict(observation, deterministic=True)
                elif idle:
                    action = np.zeros(2, dtype=np.float32)
                else:
                    action = observation[131:133]
                observation, reward, terminated, truncated, _ = environment.step(action)
                assert reward == 0 and np.all(np.isfinite(observation))
                assert np.all(np.abs(observation) <= 1.00001)
                done = terminated or truncated
                steps += 1
                assert steps <= 600
            row = records(output / 'episodes.jsonl')[-1]
            assert row['seed'] == seed and row['steps'] == steps
            assert row['completed'] or steps == 600
            if i == 0 or (i + 1) % 10 == 0:
                progress = dict(phase=name, target=len(seeds), **summary(records(output / 'episodes.jsonl')))
                save(directory / 'progress.json', progress)
                print(json.dumps(progress), flush=True)
        environment.close()
        environment = None
        finish(output, process)
        rows = records(output / 'episodes.jsonl')
        assert len(rows) == len(seeds) and [r['seed'] for r in rows] == list(seeds)
        layouts = records(output / 'layouts.jsonl')
        assert all(r['rooms'] == 2 for r in layouts)
        save(output / 'result.json', dict(status='complete', initial_route_available=sum(r['route_available'] for r in layouts), **summary(rows)))
        with (output / 'actions.jsonl').open('rb') as src, gzip.open(output / 'actions.jsonl.gz', 'wb') as dst:
            shutil.copyfileobj(src, dst)
        (output / 'actions.jsonl').unlink()
        return rows
    finally:
        if environment is not None:
            environment.close()
        if process.poll() is None:
            process.terminate()
            process.wait(timeout=30)


def run(mode):
    assert checkpoint_hash(CHECKPOINT) == SHA256
    torch.set_num_threads(1)
    model = PPO.load(CHECKPOINT, device='cpu')
    model.policy.set_training_mode(False)
    assert model.observation_contract == 'local-waypoint-v1'
    weights = {k: v.clone() for k, v in model.policy.state_dict().items()}
    counters = model.num_timesteps, model._n_updates
    stamp = datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')
    directory = GAME / 'Logs/qa-two-room-navigation' / (stamp + '-' + mode)
    directory.mkdir(parents=True)
    print('Run directory: ' + str(directory), flush=True)
    settings = {p: p.read_bytes() for p in (GAME / 'ProjectSettings').iterdir() if p.is_file()}
    hashes = {p: checkpoint_hash(GAME / p) for p in SOURCES}
    save(directory / 'run.json', dict(mode='frozen deterministic evaluation', checkpoint=str(CHECKPOINT),
        checkpoint_sha256=SHA256, model_steps=counters[0], optimizer_updates=counters[1],
        episodes=100 if mode == 'evaluate' else 0, seeds=[450000, 450099],
        generation='PcgDungeonManager.StartPlayerEpisode(parameters) -> Generator.RunProgram -> DungeonValidator',
        rooms=2, room_size=[20, 20], area_size=[100, 100], enemies=0, puzzles=0, loot=0,
        touch_exit=True, action_seconds=.1, max_actions=600, episode_seconds=60,
        navigation='Test-only oracle A* on generated floor with physical wall clearance; furthest visible clear waypoint <=10 units; replan after 20 actions without 0.05 progress',
        perception='Unmodified local-waypoint-v1, current wall/exit rays plus waypoint; oracle map is not a model input',
        source_sha256=hashes))
    try:
        # Known-direction controller checks the generator/route/exit path before using learned movement.
        reference = phase(directory, 'reference', range(450000, 450003))
        assert all(r['completed'] for r in reference), 'Reference failed; inspect geometry/heuristic before policy evaluation'
        idle = phase(directory, 'idle', [450000], idle=True)
        assert not idle[0]['completed'] and idle[0]['waypoint_arrivals'] == 0
        result = dict(status='verified', reference=summary(reference), idle=summary(idle))
        if mode == 'evaluate':
            rows = phase(directory, 'evaluation', range(450000, 450100), model=model)
            result.update(status='complete', evaluation=summary(rows))
        assert counters == (model.num_timesteps, model._n_updates)
        assert all(torch.equal(v, model.policy.state_dict()[k]) for k, v in weights.items())
        assert checkpoint_hash(CHECKPOINT) == SHA256
        assert all(checkpoint_hash(GAME / p) == digest for p, digest in hashes.items())
        result.update(weight_updates=0, model_steps=model.num_timesteps, optimizer_updates=model._n_updates,
            checkpoint_sha256=SHA256, all_weights_unchanged=True)
        save(directory / 'result.json', result)
        destination = GAME / 'SavedModels/qa/local-waypoint-v1/diagnostics' / ('two-room-navigation-' + directory.name)
        destination.mkdir(parents=True)
        for p in directory.glob('*.json'):
            shutil.copy2(p, destination / p.name)
        for name in ['reference', 'idle', 'evaluation']:
            if not (directory / name).exists():
                continue
            target = destination / name
            target.mkdir()
            for p in (directory / name).glob('*.json*'):
                shutil.copy2(p, target / p.name)
        for name in SOURCES:
            target = destination / 'source' / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(GAME / name, target)
        print(json.dumps(result, indent=2), flush=True)
        print('Retained evidence: ' + str(destination), flush=True)
    except BaseException as error:
        save(directory / 'failure.json', dict(error=str(error)))
        raise
    finally:
        for p, content in settings.items():
            if p.read_bytes() != content:
                p.write_bytes(content)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--mode', choices=['verify', 'evaluate'], default='verify')
    run(parser.parse_args().mode)
